const NEWS_CATEGORIES=['Results','All-Star','Injuries','Transactions','Draft','League','Franchise','Player Feat'];
let newsFeedUI={type:'all',scope:'all',query:'',season:'all',day:'all',group:'day',limit:30};
function newsIsInjury(text){return /\bmedical report:|\binjur(?:y|ies|ed)\b/i.test(text)}
function newsCategory(text){return /all.star/i.test(text)?'All-Star':newsIsInjury(text)?'Injuries':/draft|lottery|selects /i.test(text)?'Draft':/signs |signed |trade|release|contract/i.test(text)?'Transactions':/champion|playoff|all.star|season|deadline/i.test(text)?'League':'Franchise'}
function newsStore(){if(!state.newsFeed)state.newsFeed={nextId:1,items:[...state.news].map((text,i)=>({id:i+1,year:null,day:null,phase:'Earlier update',category:newsCategory(text),headline:text,detail:'',teams:[],game:null}))};state.newsFeed.items.forEach(n=>{if(n.category!=='Results'&&newsIsInjury(n.headline)){n.category='Injuries';for(const t of state.teams)if(n.headline.includes('('+t.abbr+')')&&!n.teams.includes(t.id))n.teams.push(t.id)}});state.newsFeed.nextId=Math.max(state.newsFeed.nextId,...state.newsFeed.items.map(n=>n.id+1),1);return state.newsFeed}
function addNewsItem(item){const feed=newsStore();feed.items.unshift({id:feed.nextId++,year:state.year,day:state.day,phase:seasonPhaseLabel(),detail:'',teams:[],game:null,...item});feed.items=feed.items.slice(0,500)}
const sayBeforeNewsFeed=say;say=function(text){newsStore();sayBeforeNewsFeed(text);const teams=state.teams.filter(t=>text.includes(t.city+' ')||text.includes(t.city+':')||text.includes(t.city+'.')).map(t=>t.id);addNewsItem({category:newsCategory(text),headline:text,teams})};
const playBeforeNewsFeed=play;play=function(a,b,stage='Regular season'){const r=playBeforeNewsFeed(a,b,stage),winner=state.teams[r.winner],loser=state.teams[r.winner===r.a?r.b:r.a],top=[...r.box].sort((a,b)=>b.pts-a.pts)[0];addNewsItem({category:'Results',headline:`${winner.city} ${winner.name} defeat ${loser.city} ${loser.name}, ${Math.max(r.sa,r.sb)}–${Math.min(r.sa,r.sb)}`,detail:top?`${top.name}: ${top.pts} PTS · ${top.reb} REB · ${top.ast} AST.`:'',teams:[a,b],day:r.day,phase:stage,game:{year:state.year,day:r.day,a:r.a,b:r.b,stage:r.stage}});return r};
function newsFeedChange(key,value){newsFeedUI[key]=value;if(key==='season')newsFeedUI.day='all';newsFeedUI.limit=30;render()}
function newsGameIndex(item){return item.game?.year===state.year?state.history.findIndex(g=>g.day===item.game.day&&g.a===item.game.a&&g.b===item.game.b&&g.stage===item.game.stage):-1}
function newsSeasonKey(n){return n.year===null?'unknown':String(n.year)}
function newsDayKey(n){return n.day===null?'unknown':String(n.day)}
function newsDateChoices(){const items=newsStore().items,seasons=[...new Set(items.map(newsSeasonKey))].sort((a,b)=>a==='unknown'?1:b==='unknown'?-1:Number(b)-Number(a));if(newsFeedUI.season!=='all'&&!seasons.includes(newsFeedUI.season)){newsFeedUI.season='all';newsFeedUI.day='all';}const days=[...new Set(items.filter(n=>newsFeedUI.season==='all'||newsSeasonKey(n)===newsFeedUI.season).map(newsDayKey))].sort((a,b)=>a==='unknown'?1:b==='unknown'?-1:Number(b)-Number(a));if(newsFeedUI.day!=='all'&&!days.includes(newsFeedUI.day))newsFeedUI.day='all';return {seasons,days}}
function newsDateControls(){const {seasons,days}=newsDateChoices();return `<label>Season<select onchange="newsFeedChange('season',this.value)"><option value="all">All seasons</option>${seasons.map(y=>`<option value="${y}" ${newsFeedUI.season===y?'selected':''}>${y==='unknown'?'Date unavailable':y+' season'}</option>`).join('')}</select></label><label>Day<select onchange="newsFeedChange('day',this.value)"><option value="all">All days</option>${days.map(d=>`<option value="${d}" ${newsFeedUI.day===d?'selected':''}>${d==='unknown'?'Date unavailable':'Day '+d}</option>`).join('')}</select></label><label>Group by<select onchange="newsFeedChange('group',this.value)">${[['day','Day'],['season','Season'],['none','Continuous feed']].map(([v,label])=>`<option value="${v}" ${newsFeedUI.group===v?'selected':''}>${label}</option>`).join('')}</select></label>`}
function newsFeedRows(){newsDateChoices();const rows=newsStore().items.filter(n=>(newsFeedUI.season==='all'||newsSeasonKey(n)===newsFeedUI.season)&&(newsFeedUI.day==='all'||newsDayKey(n)===newsFeedUI.day)&&(newsFeedUI.type==='all'||n.category===newsFeedUI.type)&&(newsFeedUI.scope==='all'||n.teams.includes(controlledTeamId()))&&(!newsFeedUI.query||(n.headline+' '+n.detail).toLowerCase().includes(newsFeedUI.query.toLowerCase())));return newsFeedUI.group==='none'?rows:rows.sort((a,b)=>(b.year??-1)-(a.year??-1)||(b.day??-1)-(a.day??-1)||b.id-a.id)}
// Resolve display text at render time; keep saved news as plain text.
function newsLinkEntities(){
 const names=new Map(),add=(name,kind,id,teamId=null)=>{if(!name||!Number.isInteger(id))return;const list=names.get(name)||[];if(!list.some(e=>e.kind===kind&&e.id===id))list.push({kind,id,teamId});names.set(name,list)};
 for(const t of state.teams){for(const name of [t.city+' '+t.name,t.city,t.name,t.abbr])add(name,'team',t.id,t.id);for(const p of t.roster)add(p.name,'player',p.id,t.id)}
 for(const p of state.free)add(p.name,'player',p.id);
 for(const p of state.draft?.prospects||[])add(p.name,'draft',p.id);
 const aliases=[...names.keys()].sort((a,b)=>b.length-a.length).map(n=>n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));
 return {names,pattern:aliases.length?new RegExp('(^|[^\\p{L}\\p{N}_])('+aliases.join('|')+')(?=$|[^\\p{L}\\p{N}_])','gu'):null};
}
function newsLinkedText(text,item,links){
 if(!links.pattern)return escapeHTML(text);let end=0,result='';links.pattern.lastIndex=0;
 for(const match of text.matchAll(links.pattern)){const start=match.index+match[1].length,name=match[2],all=links.names.get(name),tagged=all.filter(e=>item.teams?.includes(e.teamId)),choices=all.length===1?all:tagged;
 result+=escapeHTML(text.slice(end,start));const e=choices.length===1?choices[0]:null;
 if(e){const action=e.kind==='team'?'newsOpenTeam':e.kind==='draft'?'draftReport':'profile',label=e.kind==='team'?'Open team roster':e.kind==='draft'?'Open prospect profile':'Open player profile';result+=`<button type="button" class="news-entity-link" onclick="${action}(${e.id})" aria-label="${label}: ${escapeHTML(name)}">${escapeHTML(name)}</button>`}else result+=escapeHTML(name);
 end=start+name.length;
 }
 return result+escapeHTML(text.slice(end));
}
function newsOpenTeam(id){if(!state.teams.some(t=>t.id===id))return;rosterTeamId=id;go('Roster')}
function newsFeedView(){const rows=newsFeedRows(),links=newsLinkEntities();let previousGroup=null;return `<section class="panel news-feed"><div class="panelhead"><div><div class="eyebrow">${escapeHTML(state.leagueName)}</div><h2>League wire</h2></div><span class="muted">${rows.length} updates</span></div><div class="news-controls"><label>Coverage<select onchange="newsFeedChange('scope',this.value)"><option value="all" ${newsFeedUI.scope==='all'?'selected':''}>Entire league</option><option value="team" ${newsFeedUI.scope==='team'?'selected':''}>My team</option></select></label><label>News type<select onchange="newsFeedChange('type',this.value)"><option value="all">All news</option>${NEWS_CATEGORIES.map(c=>`<option ${newsFeedUI.type===c?'selected':''}>${c}</option>`).join('')}</select></label>${newsDateControls()}<label class="news-search">Search<input type="search" value="${escapeHTML(newsFeedUI.query)}" placeholder="Player, team or headline" onchange="newsFeedChange('query',this.value)"></label></div><div class="news-timeline">${rows.slice(0,newsFeedUI.limit).map(n=>{const result=newsGameIndex(n),club=state.teams[n.teams[0]],group=newsFeedUI.group==='none'?null:newsSeasonKey(n)+(newsFeedUI.group==='day'?':'+newsDayKey(n):''),heading=group!==previousGroup?`<h3 class="news-date-heading">${n.year===null?'Date unavailable':n.year+' season'}${newsFeedUI.group==='day'&&n.year!==null?' · '+(n.day===null?'Day unavailable':'Day '+n.day):''}</h3>`:'';previousGroup=group;return `${heading}<article class="news-article"><div class="news-mark">${club?'<button class="namebutton" onclick="newsOpenTeam('+club.id+')" aria-label="Open team">'+secondaryTeamLogo(club)+'</button>':gmIcon(n.category==='Transactions'?'trade':'mail')}</div><div class="news-copy"><div class="news-meta"><span>${escapeHTML(n.category)}</span><span>${n.year===null?'Earlier update · date unavailable':n.year+' season · '+escapeHTML(n.phase)+(n.day!==null?' · Day '+n.day:'')}</span></div><h3>${newsLinkedText(n.headline,n,links)}</h3>${n.detail?`<p>${newsLinkedText(n.detail,n,links)}</p>`:''}${n.featId?featNewsExtras(n):''}${!n.featId&&result>=0?`<button onclick="showResult(${result})">View results</button>`:''}</div></article>`}).join('')||'<div class="note">No news matches these filters. Try another category or advance the season.</div>'}</div>${rows.length>newsFeedUI.limit?'<div class="news-more"><button onclick="newsFeedUI.limit+=30;render()">Load more updates</button></div>':''}<p class="note">Latest 500 updates retained with your career. Earlier imported messages may not have dates or team tags.</p></section>`}
function readNewsFeed(raw,bad,count){if(raw===undefined)return undefined;if(!raw||!Number.isInteger(raw.nextId)||raw.nextId<1||!Array.isArray(raw.items)||raw.items.length>500)bad('invalid news feed');const ids=new Set();return {nextId:raw.nextId,items:raw.items.map(n=>{if(!n||!Number.isInteger(n.id)||n.id<1||ids.has(n.id)||!NEWS_CATEGORIES.includes(n.category)||typeof n.headline!=='string'||n.headline.length>2000||typeof n.detail!=='string'||n.detail.length>2000||typeof n.phase!=='string'||n.phase.length>80||n.year!==null&&(!Number.isInteger(n.year)||n.year<1900||n.year>10000)||n.day!==null&&(!Number.isInteger(n.day)||n.day<0||n.day>367)||!Array.isArray(n.teams)||n.teams.length>count||n.teams.some(id=>!Number.isInteger(id)||id<0||id>=count))bad('invalid news item');ids.add(n.id);const g=n.game;if(g&&(!Number.isInteger(g.year)||g.year<1900||g.year>10000||!Number.isInteger(g.day)||g.day<1||g.day>367||![g.a,g.b].every(id=>Number.isInteger(id)&&id>=0&&id<count)||g.a===g.b||!['Regular season','First round','Conference semifinal','Conference final','Semifinal','Championship'].includes(g.stage)))bad('invalid news result link');if(n.featId!==undefined&&(typeof n.featId!=='string'||n.featId.length>250))bad('invalid feat news reference');return {...(n.featId!==undefined?{featId:n.featId}:{}),id:n.id,year:n.year,day:n.day,phase:n.phase,category:n.category,headline:n.headline,detail:n.detail,teams:[...n.teams],game:g?{year:g.year,day:g.day,a:g.a,b:g.b,stage:g.stage}:null}})}}
